\begin{rSubsection}{Tsinghua University -- Natural Language Processing Lab (THUNLP)}{Mar 2026 -- Present}{Research Intern, AI for Science \quad | \quad Advisor: Zheni Zeng}{}
\item Co-developed MolDAS, improving molecular optimization scores by \textbf{16.1\%} over vanilla GRPO with the same expensive property-evaluation budget.
\item Built surrogate-to-oracle training with difficulty-aware sampling and targeted feedback; improved low-cost optimization scores by \textbf{3.7\%} over GRPO.
\end{rSubsection}

\begin{rSubsection}{Microsoft Research Asia (Beijing)}{Jan -- Aug 2026}{Research Intern, AI for Mathematics \quad | \quad Advisor: Xian Zhang; Collaborator: Ziyu Zhou}{}
\item Developed verifier-guided proof generation for Lean and Rzk; structural guidance improved Rzk completion by \textbf{56\%} over direct prompting (32.1\% to 50.0\%).
\item Built proof-search evaluation and replay tools that produce kernel-checked proofs, localized repair feedback, and comparable theorem-level execution traces.
\end{rSubsection}

\begin{rSubsection}{NJU Institute of Intelligent Networks and Communications (NINE)}{Aug 2026 -- Present}{Research Intern \quad | \quad Supervisor: Huihong Liang; Institute Director: Kun Yang}{}
\item Accelerated Raspberry Pi 5 video encoding by \textbf{3.57$\times$} over matched-quantization floating-point inference using packed one-bit NEON kernels.
\item Reduced model state by \textbf{93.2\%} versus floating-point storage (458.0 to 31.4 MB); deployed a Pi 5 sender sustaining 18.3 FPS.
\end{rSubsection}

\begin{rSubsection}{Wuxi Xishan NJU Institute of Applied Biotechnology}{Sep 2026 -- Present}{Research Intern, Computational Enzyme Discovery}{}
\item Delivered an enzyme-discovery workbench that converts reaction and sequence queries into experimental shortlists linked to chemical structures and literature evidence.
\end{rSubsection}

\begin{rSubsection}{Beijing Volcano Engine Technology Co., Ltd.}{Aug 2026 -- Present}{Agent Development Engineer \quad | \quad Client: Guizhou Xijiu Group}{}
\item Built Xijiu's document-agent workflow, turning retrieved company material into source-linked drafts, semantic reviews, and revised documents.
\item Integrated retrieval, model routing, and office tools through reusable adapters, delivering editable documents with source checks and persistent task state.
\end{rSubsection}

\begin{rSubsection}{Nanjing Flux Technology Co., Ltd.}{Jan 2026 -- Present}{Project Team Member \quad | \quad Client-facing software development}{}
\item Delivered backend APIs and model integrations that combine reusable services into client-facing analysis workflows.
\item \textbf{Bank of Nanjing:} built multimodal customer-emotion analysis combining audio preprocessing, speaker-aware transcription, and model inference, producing attributed transcripts and emotion labels.
\end{rSubsection}

